import React, { useContext, useState } from 'react'
import img1 from '../img/avatarpng.png'
import { ChatContext } from '../context/ChatContext'
import { AuthContext } from '../context/AuthContext'
import { Timestamp, arrayUnion, doc, serverTimestamp, updateDoc } from 'firebase/firestore'
import { db, storage } from '../firebase'
import { v4 as uuid } from 'uuid'
import { getDownloadURL, ref, uploadBytesResumable } from 'firebase/storage'

const Input = () => {

  const [text, setText] = useState('')
  const [img, setImg] = useState(null)

  const [user1, setUser1] = useState(false)
  const { currentUser } = useContext(AuthContext)
  const { data } = useContext(ChatContext)
  


  const handleSend = async () => {
    if (data.chatId === "null") return;
    if (text === '') return;
    try {

      if (img) {

        const storageRef = ref(storage, uuid());

        const uploadTask = uploadBytesResumable(storageRef, img);

        uploadTask.on(

          'state_changed',
          (snapshot) => {

            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            // console.log('Upload is ' + progress + '% done');
            switch (snapshot.state) {
              case 'paused':
                // console.log('Upload is paused');
                break;
              case 'running':
                // console.log('Upload is running');
                break;
            }
          },
          (error) => {

          },
          () => {

            getDownloadURL(uploadTask.snapshot.ref).then(async (downloadURL) => {
              await updateDoc(doc(db, 'chats', data.chatId), {
                messages: arrayUnion({
                  id: uuid(),
                  text,
                  senderId: currentUser.uid,
                  date: Timestamp.now(),
                  img: downloadURL
                }),

              })
            });


          }
        );



      } else {
        updateDoc(doc(db, 'chats', data.chatId), {
          messages: arrayUnion({
            id: uuid(),
            text,
            senderId: currentUser.uid,
            date: Timestamp.now(),

          })
        })
      }

      updateDoc(doc(db, 'userChats', currentUser.uid), {
        [data.chatId + '.lastMessage']: {
          text
        },
        [data.chatId + '.date']: serverTimestamp()
      });


      updateDoc(doc(db, 'userChats', data.user.uid), {
        [data.chatId + '.lastMessage']: {
          text
        },
        [data.chatId + '.date']: serverTimestamp()
      });

      setText('');
      setImg(null);

    } catch (error) {
      console.log(error)
    }


  }



  const handleSend1 = async (e) => {
    if (data.chatId === "null") return;
    if (text === '') return
    try {

      if (e.keyCode === 13) {
        if (img) {

          const storageRef = ref(storage, uuid());

          const uploadTask = uploadBytesResumable(storageRef, img);

          uploadTask.on(

            'state_changed',
            (snapshot) => {

              const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
              // console.log('Upload is ' + progress + '% done');
              switch (snapshot.state) {
                case 'paused':
                  // console.log('Upload is paused');
                  break;
                case 'running':
                  // console.log('Upload is running');
                  break;
              }
            },
            (error) => {

            },
            () => {

              getDownloadURL(uploadTask.snapshot.ref).then(async (downloadURL) => {
                await updateDoc(doc(db, 'chats', data.chatId), {
                  messages: arrayUnion({
                    id: uuid(),
                    text,
                    senderId: currentUser.uid,
                    date: Timestamp.now(),
                    img: downloadURL
                  }),

                })
              });


            }
          );



        } else {
          updateDoc(doc(db, 'chats', data.chatId), {
            messages: arrayUnion({
              id: uuid(),
              text,
              senderId: currentUser.uid,
              date: Timestamp.now(),

            })
          })
        }

        updateDoc(doc(db, 'userChats', currentUser.uid), {
          [data.chatId + '.lastMessage']: {
            text
          },
          [data.chatId + '.date']: serverTimestamp()
        });


        updateDoc(doc(db, 'userChats', data.user.uid), {
          [data.chatId + '.lastMessage']: {
            text
          },
          [data.chatId + '.date']: serverTimestamp()
        });

        setText('');
        setImg(null);
      }


    } catch (error) {
      console.log(error)
    }


  }

  return (
    <div className='input' >
      <input type="text" onKeyDown={handleSend1} name='input' placeholder='say something...' onChange={e => setText(e.target.value)} value={text} />
      <div className="send">

        <input type="file" style={{ display: 'none' }} id='file' onChange={e => setImg(e.target.files[0])} />
        <label htmlFor="file">
          <img src={img1} alt="" />
        </label>
        <button onClick={handleSend} >Send</button>
      </div>
    </div>
  )
}

export default Input